)
$ErrorActionPreference='Stop'
New-Item -ItemType Directory -Force -Path $Dest | Out-Null

function Expand-GzipBase64([string]$B64,[string]$Path) {
  $bytes=[Convert]::FromBase64String($B64)
  $ms=[IO.MemoryStream]::new($bytes)
  $gz=[IO.Compression.GZipStream]::new($ms,[IO.Compression.CompressionMode]::Decompress)
  $out=[IO.File]::Create($Path)
  try { $gz.CopyTo($out) } finally { $out.Dispose(); $gz.Dispose(); $ms.Dispose() }
}

$RunnerB64=@'

'@
$PatchB64=@'

'@

$Runner=Join-Path $Dest 'BONSAI2-CAPABILITY-ENVELOPE-RUNNER-v2.py'
$Patch=Join-Path $Dest 'CAPABILITY-ENVELOPE-PATCH-v4.json'
Expand-GzipBase64 $RunnerB64 $Runner
Expand-GzipBase64 $PatchB64 $Patch

$runnerSha=(Get-FileHash -Algorithm SHA256 -LiteralPath $Runner).Hash.ToLowerInvariant()
$patchSha=(Get-FileHash -Algorithm SHA256 -LiteralPath $Patch).Hash.ToLowerInvariant()
